<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu Lite Desktop</title>
    <style>
        :root {
            --ubuntu-purple: #300a24;
            --ubuntu-orange: #e95420;
            --win-bg: #333333;
            --win-header: #222222;
            --win-text: #eeeeee;
            --taskbar-bg: rgba(0, 0, 0, 0.6);
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
        }

        #desktop {
            width: 100vw;
            height: 100vh;
            background: linear-gradient(135deg, #300a24 0%, #000000 100%);
            position: relative;
            overflow: hidden;
        }

        /* Taskbar / Dock */
        #taskbar {
            position: absolute;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 15px;
            padding: 10px 20px;
            background: var(--taskbar-bg);
            border-radius: 20px;
            backdrop-filter: blur(10px);
            box-shadow: 0 4px 15px rgba(0,0,0,0.5);
            z-index: 1000;
        }

        #taskbar button {
            background: none;
            border: none;
            color: white;
            font-size: 24px;
            cursor: pointer;
            padding: 5px;
            transition: transform 0.2s, background 0.2s;
            border-radius: 8px;
        }

        #taskbar button:hover {
            transform: scale(1.2);
            background: rgba(255, 255, 255, 0.1);
        }

        /* Windows */
        .window {
            position: absolute;
            min-width: 360px;
            min-height: 240px;
            background: var(--win-bg);
            color: var(--win-text);
            border-radius: 8px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.6);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            z-index: 10;
        }

        .win-titlebar {
            height: 35px;
            background: var(--win-header);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 12px;
            cursor: move;
            user-select: none;
        }

        .win-title-text {
            font-size: 13px;
            font-weight: bold;
            color: #aaa;
        }

        .win-controls {
            display: flex;
            gap: 8px;
        }

        .win-close {
            background: none;
            border: none;
            color: #ff5f56;
            font-size: 18px;
            cursor: pointer;
            padding: 0;
            line-height: 1;
        }

        .win-close:hover {
            color: #ff2e2e;
        }

        /* Files App */
        #files-window {
            width: 500px;
            height: 350px;
            top: 100px;
            left: 100px;
        }

        #files-path {
            background: #222;
            padding: 5px 15px;
            font-size: 12px;
            color: #888;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        #files-up {
            background: #444;
            border: none;
            color: white;
            font-size: 11px;
            padding: 2px 8px;
            border-radius: 3px;
            cursor: pointer;
        }

        #files-content {
            flex-grow: 1;
            overflow-y: auto;
            padding: 10px;
        }

        .fs-item {
            display: flex;
            align-items: center;
            padding: 8px;
            cursor: pointer;
            border-radius: 4px;
            font-size: 14px;
            user-select: none;
        }

        .fs-item:hover {
            background: rgba(255, 255, 255, 0.1);
        }

        .fs-item::before {
            content: '📁';
            margin-right: 10px;
            font-size: 16px;
        }

        .fs-item.file::before {
            content: '📄';
        }

        /* Notepad App */
        #notepad-window {
            width: 450px;
            height: 400px;
            top: 150px;
            left: 400px;
        }

        #tabs {
            display: flex;
            background: #222;
            overflow-x: auto;
            scrollbar-width: none;
        }

        .tab {
            padding: 8px 15px;
            font-size: 13px;
            cursor: pointer;
            background: #333;
            border-right: 1px solid #444;
            white-space: nowrap;
        }

        .tab.active {
            background: var(--win-bg);
            border-bottom: 2px solid var(--ubuntu-orange);
        }

        #new-tab {
            background: none;
            border: none;
            color: #888;
            font-size: 18px;
            cursor: pointer;
            padding: 0 10px;
        }

        #new-tab:hover {
            color: white;
        }

        #editor {
            flex-grow: 1;
            background: #1e1e1e;
            color: #d4d4d4;
            border: none;
            resize: none;
            padding: 10px;
            font-family: 'Courier New', Courier, monospace;
            font-size: 14px;
            outline: none;
        }
    </style>
</head>
<body>

<div id="desktop">
    <!-- Taskbar -->
    <div id="taskbar">
        <button id="open-files" title="Files">📂</button>
        <button id="open-notepad" title="Notepad">📝</button>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window">
        <div class="win-titlebar">
            <span class="win-title-text">Files</span>
            <div class="win-controls">
                <button class="win-close">×</button>
            </div>
        </div>
        <div id="files-path">
            <span id="path-text">/</span>
            <button id="files-up">Up</button>
        </div>
        <div id="files-content"></div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window">
        <div class="win-titlebar">
            <span class="win-title-text">Notepad</span>
            <div class="win-controls">
                <button class="win-close">×</button>
            </div>
        </div>
        <div style="display: flex; flex-grow: 1; flex-direction: column;">
            <div id="tabs-container" style="display: flex; align-items: center; background: #222;">
                <div id="tabs"></div>
                <button id="new-tab">+</button>
            </div>
            <textarea id="editor"></textarea>
        </div>
    </div>
</div>

<script>
    // --- Data Structures ---
    const fsData = {
        '/': {
            name: '/',
            type: 'dir',
            children: {
                'bin': { type: 'dir', children: {} },
                'etc': { type: 'dir', children: {} },
                'home': {
                    type: 'dir',
                    children: {
                        'user': {
                            type: 'dir',
                            children: {
                                'Documents': { type: 'dir', children: {} },
                                'Downloads': { type: 'dir', children: {} },
                                'Pictures': { type: 'dir', children: {} },
                                'todo.txt': { type: 'file', content: 'Buy milk and bread.' },
                                'readme.txt': { type: 'file', content: 'Welcome to the Ubuntu Lite environment!' }
                            }
                        }
                    }
                },
                'usr': { type: 'dir', children: {} },
                'var': { type: 'dir', children: {} }
            }
        }
    };

    let currentPath = '/';

    let notepadState = {
        tabs: [], // { id: timestamp, title: string, content: string }
        activeTabId: null
    };

    // --- Files App Logic ---
    function getDirByPath(path) {
        const parts = path.split('/').filter(p => p.length > 0);
        let current = fsData['/'];
        for (const part of parts) {
            if (current.children && current.children[part]) {
                current = current.children[part];
            } else {
                return null;
            }
        }
        return current;
    }

    function navigateTo(path) {
        currentPath = path;
        renderFiles();
    }

    function renderFiles() {
        const pathText = document.getElementById('path-text');
        const content = document.getElementById('files-content');
        const upBtn = document.getElementById('files-up');

        pathText.innerText = currentPath;
        content.innerHTML = '';

        upBtn.style.visibility = currentPath === '/' ? 'hidden' : 'visible';

        const currentDir = getDirByPath(currentPath);
        if (!currentDir || currentDir.type !== 'dir') return;

        Object.keys(currentDir.children).forEach(name => {
            const itemData = currentDir.children[name];
            const div = document.createElement('div');
            div.className = `fs-item ${itemData.type === 'file' ? 'file' : ''}`;
            div.innerText = name;

            div.ondblclick = () => {
                if (itemData.type === 'dir') {
                    const nextPath = currentPath === '/' ? `/${name}` : `${currentPath}/${name}`;
                    navigateTo(nextPath);
                } else {
                    // If it's a file, we could open it in Notepad, but sticking to requirements
                    alert(`Content of ${name}: ${itemData.content}`);
                }
            };
            content.appendChild(div);
        });
    }

    document.getElementById('files-up').onclick = () => {
        if (currentPath === '/') return;
        const parts = currentPath.split('/').filter(p => p.length > 0);
        parts.pop();
        const newPath = '/' + parts.join('/');
        navigateTo(newPath);
    };

    // --- Notepad App Logic ---
    const editor = document.getElementById('editor');
    const tabsContainer = document.getElementById('tabs');
    const newTabBtn = document.getElementById('new-tab');

    function saveToLocalStorage() {
        localStorage.setItem('notepad_data', JSON.stringify(notepadState));
    }

    function loadFromLocalStorage() {
        const saved = localStorage.getItem('notepad_data');
        if (saved) {
            notepadState = JSON.parse(saved);
            // Ensure the active tab still exists in the list
            if (!notepadState.tabs.find(t => t.id === notepadState.activeTabId)) {
                notepadState.activeTabId = notepadState.tabs[0]?.id || null;
            }
        }

        if (!notepadState.tabs.length) {
            createTab("Untitled");
        } else {
            renderNotepad();
        }
    }

    function createTab(title = "Untitled") {
        const id = Date.now();
        notepadState.tabs.push({ id, title, content: "" });
        notepadState.activeTabId = id;
        renderNotepad();
        saveToLocalStorage();
    }

    function switchTab(id) {
        // Save current content before switching
        const currentTab = notepadState.tabs.find(t => t.id === notepadState.activeTabId);
        if (currentTab) {
            currentTab.content = editor.value;
        }

        notepadState.activeTabId = id;
        renderNotepad();
        saveToLocalStorage();
    }

    function renderNotepad() {
        // Render tabs
        tabsContainer.innerHTML = '';
        notepadState.tabs.forEach(tab => {
            const t = document.createElement('div');
            t.className = `tab ${tab.id === notepadState.activeTabId ? 'active' : ''}`;
            t.innerText = tab.title;
            t.onclick = () => switchTab(tab.id);
            tabsContainer.appendChild(t);
        });

        // Update editor
        const activeTab = notepadState.tabs.find(t => t.id === notepadState.activeTabId);
        editor.value = activeTab ? activeTab.content : "";
    }

    newTabBtn.onclick = () => createTab("Untitled");

    editor.oninput = () => {
        const activeTab = notepadState.tabs.find(t => t.id === notepadState.activeTabId);
        if (activeTab) {
            activeTab.content = editor.value;
            saveToLocalStorage();
        }
    };

    // --- Window Management ---
    function makeDraggable(win) {
        const header = win.querySelector('.win-titlebar');
        header.onmousedown = (e) => {
            bringToFront(win);
            let offsetX = e.clientX - win.offsetLeft;
            let offsetY = e.clientY - win.offsetTop;

            function onMouseMove(e) {
                win.style.left = (e.clientX - offsetX) + 'px';
                win.style.top = (e.clientY - offsetY) + 'px';
                win.style.right = 'auto'; // Reset auto positioning
                win.style.bottom = 'auto';
            }

            function onMouseUp() {
                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
            }

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        };

        win.onmousedown = () => bringToFront(win);
    }

    function bringToFront(win) {
        document.querySelectorAll('.window').forEach(w => w.style.zIndex = 10);
        win.style.zIndex = 20;
    }

    // --- Initialization ---
    window.onload = () => {
        // Setup Windows
        document.querySelectorAll('.window').forEach(win => {
            makeDraggable(win);
            win.querySelector('.win-close').onclick = () => {
                win.style.display = 'none';
            };
        });

        // Setup Launchers
        document.getElementById('open-files').onclick = () => {
            document.getElementById('files-window').style.display = 'flex';
            renderFiles();
        };
        document.getElementById('open-notepad').onclick = () => {
            document.getElementById('notepad-window').style.display = 'flex';
        };

        // Initialize Apps
        loadFromLocalStorage();
        renderFiles();
    };
</script>

</body>
</html>
